<?php
header('Content-Type:text/html;charset=UTF-8');
$ROOT=realpath(__DIR__);$SKIP=['.git','node_modules','vendor'];$TEXT='/\.(php|js|mjs|jsx|ts|tsx|css|scss|html|htm|json|xml|svg|yml|yaml|ini|conf|md|txt)$/i';
function relp($p,$r){$x=realpath($p);return $x?ltrim(str_replace('\\','/',substr($x,strlen($r))),'/'):'';}
function blocked($p){global $SKIP;foreach($SKIP as $s)if(preg_match('#(^|/)'.preg_quote($s,'#').'(/|$)#',$p))return true;return false;}
function scan_site($root){global $TEXT;$files=[];$dirs=[];$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::SELF_FIRST);foreach($it as $f){$p=relp($f->getPathname(),$root);if(!$p||blocked($p)||$p==='site-wire-live.php')continue;if($f->isDir())$dirs[]=$p;elseif($f->isFile())$files[$p]=['size'=>$f->getSize(),'text'=>(bool)preg_match($TEXT,$p)];}sort($dirs);ksort($files);$refs=[];$rx=['/\b(?:require|require_once|include|include_once)\s*\(?\s*[\'\"]([^\'\"]+)[\'\"]/i','/\b(?:import|export)\s+(?:[^\'\";]+?\s+from\s+)?[\'\"]([^\'\"]+)[\'\"]/i','/\b(?:src|href)\s*=\s*[\'\"]([^\'\"]+)[\'\"]/i','/url\(\s*[\'\"]?([^\'\"\)]+)[\'\"]?\s*\)/i'];foreach($files as $p=>$m){if(!$m['text']||$m['size']>700000)continue;$s=@file_get_contents($root.'/'.$p);if($s===false)continue;$vals=[];foreach($rx as $re){preg_match_all($re,$s,$mm);foreach($mm[1]??[] as $v){$v=trim(preg_replace('/[#?].*$/','',$v));if($v&&!preg_match('/^(https?:|data:|mailto:|javascript:|#|\/\/)/i',$v))$vals[]=$v;}}foreach(array_unique($vals) as $v){$base=dirname($p);$c=ltrim(str_replace('\\','/',($v[0]==='/'?$v:$base.'/'.$v)),'/');foreach([$c,$c.'.php',$c.'.js',$c.'.css',$c.'.json',$c.'.html',$c.'/index.php',$c.'/index.html'] as $z)if(isset($files[$z])){$refs[]=['from'=>$p,'to'=>$z];break;}}}return ['files'=>array_keys($files),'dirs'=>$dirs,'refs'=>$refs,'time'=>date('H:i:s')];}
$D=scan_site($ROOT);if(isset($_GET['pulse'])){header('Cache-Control:no-store');header('Content-Type:application/json');echo json_encode(['ok'=>1,'time'=>date('H:i:s'),'files'=>count($D['files']),'links'=>count($D['refs'])]);exit;}if(isset($_GET['data'])){header('Cache-Control:no-store');header('Content-Type:application/json');echo json_encode($D,JSON_UNESCAPED_SLASHES);exit;}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SmartToolz — Relationship Manager</title><style>
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#050b10;color:#dbe8ed;font-family:Inter,system-ui,Segoe UI,Arial}body{background:radial-gradient(circle at 50% 45%,#10232a 0,#071016 45%,#03070a 100%)}#map{position:fixed;inset:0;width:100%;height:100%;cursor:grab}.drag{cursor:grabbing!important}.top{position:fixed;z-index:5;top:18px;left:22px;right:22px;display:flex;justify-content:space-between;align-items:flex-start;pointer-events:none}.brand{font-size:19px;font-weight:800}.brand b{color:#59e2d1}.sub{margin-top:4px;color:#5b737d;font:8px ui-monospace;letter-spacing:1.3px}.stats{display:flex;gap:6px}.stat,.search,.panel,.btn{background:#09151ce8;border:1px solid #7897a41f;border-radius:9px;backdrop-filter:blur(14px)}.stat{padding:7px 10px}.stat small{display:block;color:#536c76;font:7px ui-monospace}.stat strong{font:11px ui-monospace}.live{color:#59e4b5}.search{position:fixed;z-index:6;left:22px;top:78px;width:250px;padding:10px 12px;color:#eaffff;outline:0;font:9px ui-monospace}.panel{display:none;position:fixed;z-index:7;right:22px;top:78px;width:330px;padding:15px}.panel.show{display:block}.close{float:right;border:0;background:none;color:#70868e;font-size:18px;cursor:pointer}.eyebrow{color:#58737d;font:7px ui-monospace;letter-spacing:1.5px}.panel h2{font-size:15px;margin:7px 0 3px}.path{color:#61ddd1;font:8px ui-monospace;word-break:break-all}.relations{margin-top:11px;color:#79919a;font:8px ui-monospace;line-height:1.75;max-height:300px;overflow:auto}.relations b{color:#c8d9de}.toolbar{position:fixed;z-index:6;left:22px;bottom:18px;display:flex;gap:6px}.btn{padding:8px 11px;color:#9db4bd;font:800 8px ui-monospace;cursor:pointer}.btn:hover{color:#eaffff;border-color:#59e2d155}.hint{position:fixed;z-index:5;left:50%;bottom:20px;transform:translateX(-50%);color:#526b74;font:8px ui-monospace;background:#071118cc;border:1px solid #7897a41a;border-radius:8px;padding:8px 12px}.status{position:fixed;z-index:5;right:22px;bottom:22px;color:#607983;font:8px ui-monospace}.led{display:inline-block;width:6px;height:6px;border-radius:50%;background:#59e4b5;box-shadow:0 0 11px #59e4b5;margin-right:6px}.load{position:fixed;z-index:20;inset:0;display:grid;place-items:center;background:#04090df5}.loader{text-align:center}.loader b{display:block;font-size:10px}.loader small{display:block;color:#5b747d;font:8px ui-monospace;margin-top:5px}.group{fill:#09161d;stroke:#29444d}.group.open{stroke:#58dfcf}.folder{fill:#12152a;stroke:#514581}.file{fill:#09141a;stroke:#263d45}.wire{fill:none;stroke:#2c4d55;stroke-width:1}.dep{fill:none;stroke:#3d777a;stroke-width:1.4;stroke-dasharray:5 9;animation:flow 1.5s linear infinite}.active{stroke:#58dfcf!important;opacity:1!important;stroke-width:2!important}@keyframes flow{to{stroke-dashoffset:-28px}}@media(max-width:700px){.top{left:11px;right:11px}.brand{font-size:16px}.sub{display:none}.stats .stat:nth-child(n+3){display:none}.search{left:11px;top:66px;width:195px}.panel{left:11px;right:11px;top:66px;width:auto}.toolbar{left:11px;bottom:11px}.hint{bottom:49px;white-space:nowrap}.status{right:11px;bottom:12px}}
</style></head><body><div class="load" id="load"><div class="loader"><b>SmartToolz Relationship Manager</b><small>Building clean hierarchy…</small></div></div><div class="top"><div><div class="brand"><b>◇</b> SmartToolz Relationship Manager</div><div class="sub">LIVE SERVER • GROUPED ARCHITECTURE • ACTUAL DEPENDENCIES</div></div><div class="stats"><div class="stat"><small>FILES</small><strong id="files">0</strong></div><div class="stat"><small>RELATIONS</small><strong id="rels">0</strong></div><div class="stat"><small>SERVER</small><strong class="live" id="state">LIVE</strong></div></div></div><input id="search" class="search" placeholder="Search file or folder…"><svg id="map" xmlns="http://www.w3.org/2000/svg"></svg><div id="panel" class="panel"><button id="close" class="close">×</button><div class="eyebrow">RELATIONSHIP DETAILS</div><h2 id="name"></h2><div id="path" class="path"></div><div id="relations" class="relations"></div></div><div class="toolbar"><button class="btn" id="center">CENTER</button><button class="btn" id="collapse">ALL GROUPS</button><button class="btn" id="refresh">RESCAN</button></div><div class="hint">Folder = group • click to open • click file to inspect • ESC clears</div><div class="status"><span class="led"></span>SERVER <b id="hb">CONNECTING</b></div>
<script>
const D=<?php echo json_encode($D,JSON_UNESCAPED_SLASHES);?>,svg=document.getElementById('map'),NS='http://www.w3.org/2000/svg';let W=innerWidth,H=innerHeight,zoom=.9,panX=0,panY=0,drag=false,lx=0,ly=0,hover=null,selected=null,openRoot=null,openDir=null;
const esc=s=>String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
function roots(){const s=new Set;D.files.forEach(f=>s.add(f.split('/')[0]));D.dirs.forEach(d=>s.add(d.split('/')[0]));return [...s].sort()}
function directDirs(p){return D.dirs.filter(d=>d.startsWith(p+'/')&&!d.slice(p.length+1).includes('/'))}
function directFiles(p){return D.files.filter(f=>f.startsWith(p+'/')&&!f.slice(p.length+1).includes('/'))}
function countFiles(p){return D.files.filter(f=>f===p||f.startsWith(p+'/')).length}
function relCount(p){return D.refs.filter(r=>r.from===p||r.to===p||r.from.startsWith(p+'/')||r.to.startsWith(p+'/')).length}
function make(id,path,name,type){return{id,path,name,type,x:0,y:0,w:type==='root'?190:type==='dir'?170:155,h:type==='root'?48:type==='dir'?36:30}}
function build(){const R=roots();const ns=R.map(r=>make('r:'+r,r,r+' /','root'));const by=new Map(ns.map(n=>[n.path,n]));D.dirs.forEach(d=>by.set(d,make('d:'+d,d,d.split('/').pop()+' /','dir')));D.files.forEach(f=>by.set(f,make('f:'+f,f,f.split('/').pop(),'file')));return{R,by,ns}}
function visible(){const M=build(),out=[...M.ns];for(const r of M.R){if(r!==openRoot)continue;const ds=directDirs(r),fs=directFiles(r);ds.forEach(d=>out.push(M.by.get(d)));fs.forEach(f=>out.push(M.by.get(f)));if(openDir){const ds2=directDirs(openDir),fs2=directFiles(openDir);ds2.forEach(d=>out.push(M.by.get(d)));fs2.forEach(f=>out.push(M.by.get(f)))}}return{M,out}}
function layout(){const {M,out}=visible(),R=M.ns,cx=W/2,cy=H/2;R.forEach((n,i)=>{n.x=cx+(i-(R.length-1)/2)*240;n.y=cy});if(openRoot){const r=M.by.get(openRoot),ds=directDirs(openRoot),fs=directFiles(openRoot);ds.forEach((d,i)=>{const n=M.by.get(d);n.x=r.x-230;n.y=r.y-((ds.length-1)*27)+i*54});fs.forEach((f,i)=>{const n=M.by.get(f);n.x=r.x+230;n.y=r.y-((Math.min(fs.length,18)-1)*21)+i*42;if(i>=18)n.x=r.x+395;n.y=r.y-((Math.min(fs.length-18,18)-1)*21)+(i-18)*42});if(openDir){const p=M.by.get(openDir);const ds2=directDirs(openDir),fs2=directFiles(openDir);ds2.forEach((d,i)=>{const n=M.by.get(d);n.x=p.x+220;n.y=p.y-((ds2.length-1)*24)+i*48});fs2.forEach((f,i)=>{const n=M.by.get(f);n.x=p.x+220+(i>12?170:0);n.y=p.y+55+(i%13)*39})}}return{M,out}}
function P(n){return{x:n.x*zoom+panX,y:n.y*zoom+panY}}
function wire(a,b,active,dep){const A=P(a),B=P(b),p=document.createElementNS(NS,'path'),mx=(A.x+B.x)/2,my=(A.y+B.y)/2;p.setAttribute('d',`M${A.x},${A.y} C${mx},${A.y} ${mx},${B.y} ${B.x},${B.y}`);p.setAttribute('class',(active?'active ':'')+(dep?'dep':'wire'));p.style.opacity=active?'1':dep?'.5':'.28';return p}
function isConnected(n,links){return selected&&(selected===n||links.some(e=>(e.a===selected&&e.b===n)||(e.b===selected&&e.a===n)))}
function draw(){const {M,out}=layout();svg.innerHTML='';const map=new Map(out.map(n=>[n.path,n]));const links=[];M.ns.forEach(r=>{if(r.path!==openRoot)return;directDirs(r.path).forEach(d=>map.has(d)&&links.push({a:r,b:map.get(d),dep:false}));directFiles(r.path).forEach(f=>map.has(f)&&links.push({a:r,b:map.get(f),dep:false}))});if(openDir&&map.has(openDir)){const p=map.get(openDir);directDirs(openDir).forEach(d=>map.has(d)&&links.push({a:p,b:map.get(d),dep:false}));directFiles(openDir).forEach(f=>map.has(f)&&links.push({a:p,b:map.get(f),dep:false}))}D.refs.forEach(r=>{if(map.has(r.from)&&map.has(r.to))links.push({a:map.get(r.from),b:map.get(r.to),dep:true})});const eg=document.createElementNS(NS,'g');links.forEach(e=>{const active=isConnected(e.a,links)||isConnected(e.b,links)||hover&&(e.a===hover||e.b===hover);eg.appendChild(wire(e.a,e.b,active,e.dep))});svg.appendChild(eg);const ng=document.createElementNS(NS,'g');out.forEach(n=>{const p=P(n),active=n===selected||n===hover||isConnected(n,links),g=document.createElementNS(NS,'g');const r=document.createElementNS(NS,'rect');r.setAttribute('x',p.x-n.w/2);r.setAttribute('y',p.y-n.h/2);r.setAttribute('width',n.w);r.setAttribute('height',n.h);r.setAttribute('rx',n.type==='root'?10:7);r.setAttribute('class',n.type==='root'?'group '+(n.path===openRoot?'open':''):n.type==='dir'?'folder':'file');if(active)r.classList.add('active');g.appendChild(r);const t=document.createElementNS(NS,'text');t.setAttribute('x',p.x);t.setAttribute('y',p.y+3);t.setAttribute('text-anchor','middle');t.setAttribute('fill',active?'#edffff':n.type==='root'?'#76ddd3':n.type==='dir'?'#a69af0':'#82969e');t.setAttribute('font-family','ui-monospace,monospace');t.setAttribute('font-size',n.type==='root'?'10':n.type==='dir'?'8.5':'8');t.textContent=(n.type==='root'?'▣ ':n.type==='dir'?'▰ ':'')+n.name;g.appendChild(t);const c=document.createElementNS(NS,'text');if(n.type!=='file'){c.setAttribute('x',p.x);c.setAttribute('y',p.y+16);c.setAttribute('text-anchor','middle');c.setAttribute('fill','#506974');c.setAttribute('font-family','ui-monospace,monospace');c.setAttribute('font-size','7');c.textContent=countFiles(n.path)+' files • '+relCount(n.path)+' links';g.appendChild(c)}g.addEventListener('click',e=>{e.stopPropagation();select(n)});ng.appendChild(g)});svg.appendChild(ng);document.getElementById('files').textContent=D.files.length;document.getElementById('rels').textContent=D.refs.length}
function select(n){if(!n){selected=null;openRoot=null;openDir=null;document.getElementById('panel').classList.remove('show');draw();return}selected=n;if(n.type==='root'){openRoot=openRoot===n.path?null:n.path;openDir=null}else if(n.type==='dir'){openRoot=n.path.split('/')[0];openDir=openDir===n.path?null:n.path}document.getElementById('panel').classList.add('show');document.getElementById('name').textContent=n.name;document.getElementById('path').textContent=n.path;const rel=n.type==='file'?D.refs.filter(r=>r.from===n.path||r.to===n.path):D.refs.filter(r=>r.from.startsWith(n.path+'/')||r.to.startsWith(n.path+'/'));document.getElementById('relations').innerHTML='<b>'+rel.length+' actual relationships</b><br>'+rel.slice(0,120).map(r=>'↳ '+esc(r.from)+' → '+esc(r.to)).join('<br>')+(rel.length>120?'<br>…':'');draw()}
function hit(mx,my){const {out}=visible();let best=null,bd=24;out.forEach(n=>{const p=P(n),d=Math.hypot(mx-p.x,my-p.y);if(d<bd){bd=d;best=n}});return best}
svg.addEventListener('pointerdown',e=>{drag=true;lx=e.clientX;ly=e.clientY;svg.classList.add('drag')});addEventListener('pointermove',e=>{if(drag){panX+=e.clientX-lx;panY+=e.clientY-ly;lx=e.clientX;ly=e.clientY;draw()}else{const n=hit(e.clientX,e.clientY);if(n!==hover){hover=n;draw()}}});addEventListener('pointerup',()=>{drag=false;svg.classList.remove('drag')});svg.addEventListener('click',()=>select(null));svg.addEventListener('wheel',e=>{e.preventDefault();const old=zoom;zoom=Math.max(.45,Math.min(2.2,zoom*(e.deltaY<0?1.1:.9)));panX=e.clientX-(e.clientX-panX)*(zoom/old);panY=e.clientY-(e.clientY-panY)*(zoom/old);draw()},{passive:false});document.getElementById('close').onclick=()=>select(null);document.getElementById('center').onclick=()=>{zoom=.9;panX=0;panY=0;draw()};document.getElementById('collapse').onclick=()=>select(null);document.getElementById('refresh').onclick=()=>location.reload();document.getElementById('search').oninput=e=>{const q=e.target.value.toLowerCase().trim();if(!q){select(null);return}const path=D.files.find(f=>f.toLowerCase().includes(q))||D.dirs.find(d=>d.toLowerCase().includes(q));if(path){const type=D.files.includes(path)?'file':'dir';select({id:(type==='file'?'f:':'d:')+path,path,name:path.split('/').pop()+(type==='dir'?' /':''),type})}};addEventListener('keydown',e=>{if(e.key==='Escape')select(null)});async function heartbeat(){try{const r=await fetch(location.pathname+'?pulse=1&t='+Date.now(),{cache:'no-store'}),d=await r.json();document.getElementById('hb').textContent=d.time;document.getElementById('state').textContent='LIVE'}catch(e){document.getElementById('hb').textContent='OFFLINE';document.getElementById('state').textContent='OFFLINE'}}draw();heartbeat();setInterval(heartbeat,2000);
</script></body></html>